import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppUserPasswordReset } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppUserPasswordReset";
import { UserPayload } from "../decorators/payload/UserPayload";

export async function patchTodoAppUserUsersPasswordResets(props: {
  user: UserPayload;
  body: ITodoAppUserPasswordReset.IRequest;
}): Promise<void> {
  // Find the reset request by token ensuring it is valid (not expired, not deleted)
  const resetRequest =
    await MyGlobal.prisma.todo_app_user_password_resets.findFirst({
      where: {
        token: props.body.token,
        expires_at: { gt: toISOStringSafe(new Date()) },
        deleted_at: null,
      },
    });
  if (resetRequest === null) {
    throw new HttpException("Invalid or expired reset token.", 400);
  }
  // Hash the new password
  const hashedPassword = await PasswordUtil.hash(props.body.password);
  // Update the user's password
  await MyGlobal.prisma.todo_app_users.update({
    where: { id: resetRequest.todo_app_user_id },
    data: {
      password_hash: hashedPassword,
      updated_at: toISOStringSafe(new Date()),
    },
  });
  // Invalidate the used reset token by setting deleted_at
  const nowISOString = toISOStringSafe(new Date());
  await MyGlobal.prisma.todo_app_user_password_resets.update({
    where: { id: resetRequest.id },
    data: {
      deleted_at: nowISOString,
      updated_at: nowISOString,
    },
  });
}

import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuest";
import { ITodoAppAccessToken } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAccessToken";

export async function postTodoAppAuthGuestRefresh(props: {
  body: ITodoAppGuest.IRefresh;
}): Promise<ITodoAppGuest.IAuthorized> {
  let decodedRaw: unknown;
  try {
    decodedRaw = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    );
  } catch {
    throw new HttpException("Invalid or expired refresh token", 401);
  }
  if (
    typeof decodedRaw !== "object" ||
    decodedRaw === null ||
    !("id" in decodedRaw) ||
    !("session_id" in decodedRaw) ||
    !("type" in decodedRaw) ||
    (decodedRaw as any).type !== "guest"
  ) {
    throw new HttpException("Invalid token type or payload", 403);
  }
  const decoded = decodedRaw as {
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    type: "guest";
  };
  const session = await MyGlobal.prisma.todo_app_guest_sessions.findFirst({
    where: {
      id: decoded.session_id,
    },
    select: {
      id: true,
      expired_at: true,
      created_at: true,
    },
  });
  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  const guest = await MyGlobal.prisma.todo_app_guests.findUnique({
    where: { id: decoded.id },
    select: {
      id: true,
      deleted_at: true,
    },
  });
  if (!guest) {
    throw new HttpException("Guest not found", 404);
  }
  if (guest.deleted_at !== null) {
    throw new HttpException("Guest account has been deleted", 403);
  }
  const nowIso = toISOStringSafe(new Date()) as string &
    tags.Format<"date-time">;
  const accessExpiredAt = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  ) as string & tags.Format<"date-time">;
  const refreshExpiredAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  ) as string & tags.Format<"date-time">;
  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  await MyGlobal.prisma.todo_app_guest_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpiredAt },
  });
  return {
    id: decoded.id,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiredAt,
      refreshable_until: refreshExpiredAt,
    },
  };
}

import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
